x=pd.read_csv(\"respondents.csv\"); prices=[4,7,10,13]; pairs=list(itertools.combinations(prices,2))
def base(d):
 w=d.wt_design; return [len(d),round(w.sum(),4),round(w.sum()**2/(w*w).sum(),4)]
def est(d,y):
 w=d.wt_design.to_numpy(); y=np.asarray(y); m=np.sum(w*y)/sum(w); v=len(w)/(len(w)-1)*sum(w*w*(y-m)**2)/sum(w)**2; return [m,v]
def fmt(m,v): return [round(m,6),round(m-1.95996398454*np.sqrt(v),6),round(m+1.95996398454*np.sqrt(v),6)]
def shares(d,col):
 return {str(k):round(g.wt_design.sum()/d.wt_design.sum(),6) for k,g in d.groupby(col,dropna=False)}
A={}; Q={}; Z={}
for p in prices:
 d=x[x.assigned_price_gbp==p]; v=d[d.intent_5.isin([1,2,3,4,5])]; Q[p]=est(v,v.intent_5.isin([4,5])); Z[p]=est(d,d.intent_5.isin([4,5])); miss={str(k):{\"n\":int((d.intent_5==k).sum()),\"share\":round(d.loc[d.intent_5==k,\"wt_design\"].sum()/d.wt_design.sum(),6)} for k in [97,98,99]}; miss[\"blank\"]={\"n\":int(d.intent_5.isna().sum()),\"share\":round(d.loc[d.intent_5.isna(),\"wt_design\"].sum()/d.wt_design.sum(),6)}
 A[p]={\"assigned_base\":base(d),\"module_base\":base(d[d.postprice_responded==1]),\"valid_base\":base(v),\"distribution\":shares(v,\"intent_5\"),\"missing\":miss,\"qv\":fmt(*Q[p]),\"q0\":fmt(*Z[p]),\"bounds\":[Z[p][0],Z[p][0]+1-v.wt_design.sum()/d.wt_design.sum()],\"profile\":{c:shares(d,c) for c in [\"age_band\",\"household_children\",\"budget_band\",\"meal_planning_role\",\"weekday_time_pressure_5\",\"current_planning_method\",\"digital_confidence_5\",\"plan_ahead_days_7\",\"subscription_spend_band\",\"household_size_band\",\"time_pressed_family\",\"design_stratum\"]},\"financial\":{str(c):{\"valid\":fmt((p-c)*Q[p][0],(p-c)**2*Q[p][1]),\"assigned\":fmt((p-c)*Z[p][0],(p-c)**2*Z[p][1])} for c in [0,0.5,2,3]}}
def tests(rows):
 out=[]
 for label,m,v in rows:
  pv=math.erfc(abs(m/np.sqrt(v))/np.sqrt(2)); out.append({\"pair\":label,\"estimate_ci\":fmt(m,v),\"raw_p\":pv})
 order=sorted(range(len(out)),key=lambda i:out[i][\"raw_p\"]); prev=0
 for j,i in enumerate(order):
  prev=max(prev,min(1,(len(out)-j)*out[i][\"raw_p\"])); out[i][\"holm_p\"]=prev
 return out
T={}
for name,q,costs in [(\"P1\",Q,[None]),(\"P2\",Z,[None]),(\"P3\",Q,[0]),(\"P4\",Q,[0.5,2,3])]:
 rows=[]
 for c in costs:
  for a,b in pairs:
   ka,kb=(1,1) if c is None else (a-c,b-c); rows.append(([a,b,c],ka*q[a][0]-kb*q[b][0],ka**2*q[a][1]+kb**2*q[b][1]))
 T[name]=tests(rows)
S={}; rows=[]
for p in [7,10]:
 ss={}
 for g in [0,1,97]:
  d=x[(x.assigned_price_gbp==p)&(x.time_pressed_family==g)]; v=d[d.intent_5.isin([1,2,3,4,5])]; ss[g]={\"eligible\":base(d),\"valid\":base(v)}
  if len(v)>=40: ss[g][\"q\"]=est(v,v.intent_5.isin([4,5])); ss[g][\"estimate_ci\"]=fmt(*ss[g][\"q\"])
 S[p]=ss; rows.append((p,ss[1][\"q\"][0]-ss[0][\"q\"][0],ss[1][\"q\"][1]+ss[0][\"q\"][1]))
T[\"P5\"]=tests(rows)
N={}
for p in prices:
 d=x[(x.assigned_price_gbp==p)&x.age_band.isin([3,4])&(x.budget_band==3)&(x.current_planning_method==4)]; N[p]={\"eligible\":base(d),\"valid\":base(d[d.intent_5.isin([1,2,3,4,5])]),\"status\":\"suppressed\"}
print(json.dumps({\"arms\":A,\"tests\":T,\"audience\":S,\"niche\":N},allow_nan=False))'"

